    _FLAT_TONICS = {"F", "Bb", "Eb", "Ab", "Db", "Gb", "d", "g", "c", "f", "bb", "eb"}
    _STEPS = {"m": 1, "M": 2, "A": 3}

    def __init__(self, tonic):
        # Preserve the tonic's case when choosing major/minor spelling.
        self.tonic = tonic.capitalize()
        self._notes = self._FLATS if tonic in self._FLAT_TONICS else self._SHARPS
        self._start = self._notes.index(self.tonic)

    def chromatic(self):
        """Return the twelve pitches ascending from the tonic."""
        return list(self._notes[self._start:] + self._notes[:self._start])

    def interval(self, intervals):
        """Return the tonic followed by one pitch for each interval."""
        position = self._start
        notes = [self.tonic]
        for interval in intervals:
            position = (position + self._STEPS[interval]) % len(self._notes)
            notes.append(self._notes[position])
        return notes
