from scale_generator import Scale


class ScaleTests(unittest.TestCase):
    def test_chromatic_spelling_for_all_documented_tonics(self):
        sharps = ["A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#"]
        flats = ["A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab"]
        groups = (
            ("C a G D A E B F# e b f# c# g# d#".split(), sharps),
            ("F Bb Eb Ab Db Gb d g c f bb eb".split(), flats),
        )
        for tonics, pitches in groups:
            for tonic in tonics:
                with self.subTest(tonic=tonic):
                    start = pitches.index(tonic.capitalize())
                    expected = pitches[start:] + pitches[:start]
                    self.assertEqual(Scale(tonic).chromatic(), expected)

    def test_major_scale(self):
        self.assertEqual(
            Scale("G").interval("MMmMMMm"),
            ["G", "A", "B", "C", "D", "E", "F#", "G"],
        )

    def test_minor_scale_uses_flats(self):
        self.assertEqual(
            Scale("g").interval("MmMMmMM"),
            ["G", "A", "Bb", "C", "D", "Eb", "F", "G"],
        )

    def test_augmented_intervals(self):
        self.assertEqual(
            Scale("d").interval("MmMMAm"),
            ["D", "E", "F", "G", "A", "C", "Db"],
        )

    def test_empty_pattern_returns_only_tonic(self):
        self.assertEqual(Scale("bb").interval(""), ["Bb"])

    def test_partial_scale(self):
        self.assertEqual(Scale("C").interval("MmA"), ["C", "D", "D#", "F#"])

    def test_wraps_across_multiple_octaves(self):
        self.assertEqual(Scale("F#").interval("A" * 8),
                         ["F#", "A", "C", "D#", "F#", "A", "C", "D#", "F#"])

    def test_calls_do_not_change_the_scale(self):
        scale = Scale("C")
        expected = scale.chromatic()
        scale.interval("MMmMMMm")
        changed = scale.chromatic()
        changed[0] = "changed"
        self.assertEqual(scale.chromatic(), expected)
        self.assertEqual(scale.interval("M"), ["C", "D"])


if __name__ == "__main__":
    unittest.main()
